Built this cache for my hobby weather dashboard. Be as blunt as you like, I'm curious how it reads to someone else.
```js
class LRU {
  #max; #map = new Map();
  constructor(max) { this.#max = max; }
  get(k) {
    if (!this.#map.has(k)) return;
    const v = this.#map.get(k);
    this.#map.delete(k);
    this.#map.set(k, v);
    return v;
  }
  set(k, v) {
    this.#map.delete(k);
    this.#map.set(k, v);
    if (this.#map.size > this.#max)
      this.#map.delete(this.#map.keys().next().value);
  }
}
```

